-- Starter content for the studio site: Zora, their guide categories and guides.
-- Generated by scripts/content-sql.mjs from content/guides/*.json — edit those, not this file.
-- Safe on a database that already has content: existing products, categories and guides are left alone.

insert into public.ad_settings (id) values (1) on conflict (id) do nothing;

-- Zora ---------------------------------------------------------------
insert into public.products (slug, name, kind, headline, headline_em, headline_style, description, highlights, cta_label, cta_url, site_url, accent_dark, accent_light, button_dark, button_light, status, sort_order)
values ($c$zora$c$, $c$Zora$c$, $c$Clock & live weather for your car$c$, $c$Dusk to dawn,$c$, $c$she keeps watch.$c$, $c$sans$c$, $c$A calm, landscape clock for your car's screen, with a live weather sky behind the time. Free with one small, still ad and no sign-up; go ad-free on up to five screens.$c$, $c$[{"label":"Weather sky","value":"Live"},{"label":"Sign-up","value":"Not needed"},{"label":"Offline","value":"Keeps time"}]$c$::jsonb, $c$Open Zora$c$, $c$https://zoraapp.midnightpoetry.studio/$c$, $c$https://zora.midnightpoetry.studio/$c$, $c$#7FD3C3$c$, $c$#1A6B5F$c$, $c$#F2A365$c$, $c$#A84E22$c$, 'live', 3)
on conflict (slug) do nothing;

insert into public.categories (product_id, name, slug, sort_order)
