cross join (values ($c$Getting started$c$, $c$getting-started$c$, 1), ($c$Sky and weather$c$, $c$sky-and-weather$c$, 2), ($c$Settings$c$, $c$settings$c$, 3), ($c$Ad-free and account$c$, $c$ad-free-and-account$c$, 4), ($c$Privacy$c$, $c$privacy$c$, 5)) as c(name, slug, ord)
where p.slug = $c$zora$c$
