insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$setting-up-zora-on-your-car-screen$c$, $c$Setting up Zora on your car screen$c$, $c$Open one address, add it to the home screen, choose your weather location, and you're done. Here is the whole set-up — best done while parked.$c$, $c$[{"type":"callout","title":"The short version","text":"On the car's screen, open **zoraapp.midnightpoetry.studio**, add it to the home screen, then in **Settings** turn on **Full screen** and **Keep the screen on**. No sign-up needed."},{"type":"heading","text":"Which screens it works on"},{"type":"paragraph","text":"Zora is a web app made for wide, landscape screens: the browser on a car's head unit, an Android head unit, or a tablet mounted on the dash — right up to very wide 32:9 dashboards. It doesn't run inside CarPlay or Android Auto, because those can't open web apps."},{"type":"heading","text":"Step by step"},{"type":"list","ordered":true,"items":["Park somewhere safe.","Open **zoraapp.midnightpoetry.studio** in the screen's browser.","Add it to the home screen. It then opens full screen and keeps working offline.","Allow location when the browser asks — or choose a city instead (see below).","Open **Settings** and check **Full screen** and **Keep the screen on** are both on."]},{"type":"heading","text":"Location or a city"},{"type":"paragraph","text":"With **My location**, Zora uses your approximate position, rounded to about 1 km. Prefer not to share it? In **Settings › Background**, choose **A city** and search for one — no location needed."},{"type":"heading","text":"If it asks you to turn the screen"},{"type":"paragraph","text":"On a portrait or narrow screen you'll see “Turn your screen sideways”. Rotate the device or turn off rotation lock. Setting up on your phone first is fine — rotate it, and your choices are saved on that device."},{"type":"faq","items":[{"q":"Do I need an account?","a":"No. Zora is free with one small, still ad. An account is only for going ad-free."},{"q":"Does it work without signal?","a":"Yes. The clock keeps time offline, in tunnels and car parks. The weather comes back on its own when you're online again."}]},{"type":"cta","title":"On your screen in a minute.","text":"No sign-up needed.","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Set up Zora on your car's screen | Zora$c$, $c$Open Zora in your car screen's browser, add it to the home screen, turn on full screen and keep-awake, and choose your location or a city.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$made-to-be-glanced-at$c$, $c$Made to be glanced at: using Zora safely$c$, $c$Zora is designed to sit quietly on the dash and be read in a second. Here is how it keeps out of your way, and the one rule that matters.$c$, $c$[{"type":"callout","title":"The short version","text":"Set Zora up while parked. After that it just keeps time — big, clear, and nothing to tap while you drive. Always follow your local road rules."},{"type":"heading","text":"How it stays calm"},{"type":"list","ordered":false,"items":["**Big, clear time** — readable at a glance from the driver's seat.","**Nothing moves except the sky** — no flashing numbers, no animated ads.","**No pop-ups** — Zora never interrupts with messages or prompts while it's running.","**One still ad on the free plan** — a single small image, with no animation, video or sound.","**Quiet by default** — weather sounds only start when you tap the speaker."]},{"type":"heading","text":"Before you set off"},{"type":"paragraph","text":"Choose your clock style, world clocks, background and location while the car is parked. If you want to look at the full forecast, open the weather pane when you've stopped — the weather pill on the main screen tells you enough on the move."},{"type":"heading","text":"What Zora isn't"},{"type":"paragraph","text":"Zora is a clock with a weather sky. It isn't a navigation or safety service, and weather forecasts can be wrong — trust what you see out of the window."},{"type":"faq","items":[{"q":"Can a passenger change settings while driving?","a":"Yes — settings are on the device itself, so whoever is safely able to tap the screen can open them."},{"q":"Will the screen stay on?","a":"With **Keep the screen on** turned on, yes, while Zora is open. Some battery-saver modes can override it."}]},{"type":"cta","title":"Calm on the dash.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Using Zora safely while you drive | Zora$c$, $c$How Zora is designed for a glance — big time, no pop-ups, one still ad — and why you should set it up while parked.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$getting-started$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$realistic-3d-illustrated-2d-or-aurora$c$, $c$Realistic 3D, illustrated 2D or your aurora$c$, $c$The sky behind the time follows the weather outside. Here are the three ways it can look, and when Zora switches between them by itself.$c$, $c$[{"type":"callout","title":"The short version","text":"In **Settings › Background**, choose **Realistic 3D**, **Illustrated 2D** or **Off** (your aurora only). Older screens run best with **Eco mode** on."},{"type":"heading","text":"The three backgrounds"},{"type":"table","caption":"Settings › Background › Weather background.","header":["Choice","What you see","Good for"],"rows":[["Realistic 3D","A live sky: lit clouds, rain, lightning, stars, moon and sun","Newer screens and tablets"],["Illustrated 2D","The same weather as flat illustrations","Lighter on older head units"],["Off","Just your aurora colour","A minimal look"]]},{"type":"paragraph","text":"The sky follows the weather where you are — rain, storm, cloud, fog, sun — and shows day or night from the real sun position, not from your light or dark theme."},{"type":"heading","text":"Raindrops and Eco mode"},{"type":"list","ordered":false,"items":["**Raindrops on the glass** adds drops when it's raining. Turn it off for a cleaner look.","**Eco mode** uses 2D weather at 30 frames a second — easier on older head units and batteries."]},{"type":"heading","text":"When Zora switches by itself"},{"type":"paragraph","text":"If 3D runs too slowly on a screen, Zora shows 2D for the rest of that session and says “showing 2D on this screen”. It tries 3D again the next time you open it. When there's no up-to-date weather — no location, no signal, or a report more than an hour old — Zora shows your aurora until the weather comes back."},{"type":"faq","items":[{"q":"Why does my sky look flat?","a":"You may be on Illustrated 2D or Eco mode, or the screen may not support 3D. Check **Settings › Background**."},{"q":"Does the sky drain the battery?","a":"3D does more work. Eco mode or Illustrated 2D are lighter if your screen runs warm or slow."}]},{"type":"cta","title":"Real weather. Right there.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Zora's weather sky: 3D, 2D or aurora | Zora$c$, $c$Choose a realistic 3D or illustrated 2D weather sky, or just your aurora — plus Eco mode, raindrops on the glass, and why Zora sometimes shows 2D.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$sky-and-weather$c$
where p.slug = $c$zora$c$
