insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$reading-the-weather-pane$c$, $c$Reading the weather pane$c$, $c$Tap the weather pill or swipe left for the full picture: feels-like, rain, wind, UV, daylight left and the next 24 hours.$c$, $c$[{"type":"callout","title":"The short version","text":"Open it from the weather pill, the handle on the right edge, or a swipe left. Close it with a swipe right or **Back to clock**."},{"type":"heading","text":"At the top"},{"type":"paragraph","text":"The place name and when the report was updated. If it's getting old you'll see “out of date”. The big temperature sits below, with **Feels like**, today's **High** and **Low**."},{"type":"heading","text":"The four facts"},{"type":"table","caption":"Read across in one glance.","header":["Fact","What it tells you"],"rows":[["Rain","The chance of rain (or the amount, where a chance isn't given)"],["Humidity","How muggy it feels"],["Wind","Speed in km/h and the direction it's coming from"],["UV","The index and a word: Low, Moderate, High, Very high or Extreme"]]},{"type":"heading","text":"Daylight and the heads-up line"},{"type":"paragraph","text":"The **Daylight** arc shows how much light is left today, or when the sun rises at night. One line underneath gives the thing most worth knowing next — like “Rain likely from 4 pm” or “Thunder likely around 6 pm”."},{"type":"heading","text":"The next 24 hours"},{"type":"paragraph","text":"A row of hours with the temperature and chance of rain, so you can see a wet commute coming."},{"type":"faq","items":[{"q":"Where does the weather come from?","a":"From the Norwegian Meteorological Institute (MET Norway). It refreshes every 10 minutes while Zora is on screen."},{"q":"Can I see wind in mph?","a":"Not yet — only temperature switches between °C and °F."}]},{"type":"cta","title":"The next 24 hours, one swipe away.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$How to read Zora's weather pane | Zora$c$, $c$What every part of Zora's weather pane means — temperature, feels like, rain, humidity, wind, UV, daylight and the next 24 hours.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$sky-and-weather$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$why-zora-is-showing-the-aurora$c$, $c$No weather? Why Zora is showing your aurora$c$, $c$When the weather can't load, Zora shows your aurora instead and keeps trying. Here is what each message means and what to do.$c$, $c$[{"type":"callout","title":"The short version","text":"Zora needs your location or a city to show the weather. If location is off, tap **Choose a city**. If you're offline, wait — the weather comes back on its own."},{"type":"heading","text":"What the message means"},{"type":"table","caption":"Shown under the clock.","header":["Message","What to do"],"rows":[["Finding the weather…","Nothing — it's loading."],["Weather needs your location or a city. Showing your aurora.","Tap **Choose a city**, or allow location."],["Location is off for Zora. Showing your aurora.","Allow location in the browser's site settings, or tap **Choose a city**."],["Offline. The weather comes back on its own.","Nothing — Zora retries when you're back online."],["Weather isn't available right now. Showing your aurora.","Tap **Retry**, or wait a few minutes."]]},{"type":"heading","text":"Why old weather isn't shown"},{"type":"paragraph","text":"Zora keeps the last report on the device, but only trusts it for an hour. After that it would rather show your aurora than yesterday's rain."},{"type":"heading","text":"Using a city instead"},{"type":"paragraph","text":"In **Settings › Background**, choose **A city** and search. This never needs your location, and it's handy if your car's browser keeps forgetting the permission."},{"type":"faq","items":[{"q":"The clock still works offline?","a":"Yes. Time never needs a connection."},{"q":"City search says it isn't available.","a":"Search needs a connection. Try again once you're online."}]},{"type":"cta","title":"Your aurora, until the sky clears.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Zora shows the aurora instead of weather | Zora$c$, $c$What Zora's weather messages mean — location off, offline, weather unavailable — and how to get the live sky back.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$sky-and-weather$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$choosing-your-aurora-colour$c$, $c$Choosing your aurora colour$c$, $c$The aurora is Zora's calm backdrop when there's no weather, or all the time if you prefer. Pick a preset or your own colour.$c$, $c$[{"type":"callout","title":"The short version","text":"In **Settings › Background**, tap a colour under the aurora presets — or **Your own** to pick any colour. Zora pairs it with a neighbouring shade for a soft glow."},{"type":"heading","text":"The presets"},{"type":"paragraph","text":"Zora (the default teal and violet), Teal, Ocean, Violet, Orchid, Rose, Dawn, Gold and Mint. Each one is paired with a neighbouring colour for a soft, two-tone glow."},{"type":"heading","text":"Your own colour"},{"type":"paragraph","text":"Choose **Your own** and use the colour picker. Match your car's interior lighting, or pick something calm for night drives."},{"type":"heading","text":"Aurora only"},{"type":"paragraph","text":"Prefer no weather sky at all? Set **Weather background** to **Off**. You'll still have the weather pill and pane — just the aurora behind the time."},{"type":"faq","items":[{"q":"Is the colour saved?","a":"Yes, on this screen. Settings stay on each device and never leave it."}]},{"type":"cta","title":"Your aurora. Your colour.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Choose your aurora colour in Zora | Zora$c$, $c$Pick one of Zora's aurora colour presets or your own colour, and use the aurora on its own as a minimal background.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$sky-and-weather$c$
where p.slug = $c$zora$c$
