insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$clock-styles-and-world-clocks$c$, $c$Clock styles and world clocks$c$, $c$Digital, analog or both, 12 or 24 hours, and up to four world clocks along the bottom — with a note when it's already tomorrow there.$c$, $c$[{"type":"callout","title":"The short version","text":"**Settings › Clock** sets the style, hour format and seconds. **World clocks** holds up to four cities."},{"type":"heading","text":"The clock"},{"type":"list","ordered":false,"items":["**Clock style** — Digital, Analog or Both.","**Hour format** — 12-hour (with AM/PM) or 24-hour.","**Show seconds** — off by default, for a calmer screen."]},{"type":"heading","text":"World clocks"},{"type":"paragraph","text":"Up to four cities sit along the bottom of the screen. Add one with **Add a city**, remove any you don't need. When a city's date is different from yours, it's marked **Tomorrow** or **Yesterday**, so you never call someone at 3 am by mistake."},{"type":"faq","items":[{"q":"Which world clocks are there by default?","a":"Tokyo, London and New York. Change them to anywhere you like."},{"q":"Does it handle daylight saving?","a":"Yes — each city keeps its own local time."}]},{"type":"cta","title":"Every clock you need.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Clock styles and world clocks in Zora | Zora$c$, $c$Switch between digital, analog or both, 12- or 24-hour time, show seconds, and add up to four world clocks to Zora.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settings$c$
where p.slug = $c$zora$c$
