insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$keep-the-screen-on-and-full-screen$c$, $c$Keep the screen on, full screen and updates$c$, $c$The settings that make Zora feel built into the dash, what to do if the screen still sleeps, and how updates arrive.$c$, $c$[{"type":"callout","title":"The short version","text":"In **Settings › Appearance**, turn on **Keep the screen on** and **Full screen**. Both are best with Zora added to the home screen."},{"type":"heading","text":"Keep the screen on"},{"type":"paragraph","text":"While Zora is open, it asks the screen not to sleep. Some battery-saver modes overrule that request — if your screen still dims, check the device's own battery or display settings."},{"type":"heading","text":"Full screen"},{"type":"paragraph","text":"Hides the browser bars where your screen allows it, and keeps Zora in landscape. Added to the home screen, Zora opens full screen anyway."},{"type":"heading","text":"Theme"},{"type":"paragraph","text":"**System** follows your device's light or dark setting. Choose **Light** or **Dark** to fix it. The sky itself always follows the real time of day."},{"type":"heading","text":"Updates"},{"type":"paragraph","text":"When a new version is ready, Zora says “A new version of Zora is ready.” with **Later** or **Reload**. It never reloads by itself, so the screen won't blink mid-drive."},{"type":"heading","text":"Starting fresh"},{"type":"paragraph","text":"Settings are saved on each device. **Settings › About › Reset to defaults** puts everything back — and clearing the browser's data does the same."},{"type":"faq","items":[{"q":"Will Zora still work when it's offline?","a":"Yes. Once added to the home screen, the clock and app keep working offline; the weather comes back when you're online."}]},{"type":"cta","title":"Built into the dash, almost.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Keep Zora on screen and full screen | Zora$c$, $c$Turn on Keep the screen on and Full screen, fix a screen that still goes to sleep, and how Zora updates and resets.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settings$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$ambient-weather-sounds$c$, $c$Ambient weather sounds$c$, $c$Soft rain, a light breeze, a quiet night: Zora can play a gentle sound that matches the sky. Nothing plays until you tap it.$c$, $c$[{"type":"callout","title":"The short version","text":"Tap the speaker at the top right to play the sound for the current weather. Tap again to mute. Set the volume in **Settings › Sound & weather**."},{"type":"heading","text":"The sounds"},{"type":"paragraph","text":"Soft rain, Thunder and rain, Light breeze, Still air and Quiet night — matched to the weather outside. The weather pane also has an Ambient control to play or mute it."},{"type":"heading","text":"Settings"},{"type":"list","ordered":false,"items":["**Ambient weather sound** — turns the sound on; it still only starts when you tap the speaker. Off to start with.","**Ambient volume** — 60% by default; keep it low under music or calls."]},{"type":"faq","items":[{"q":"Will a sound start by itself?","a":"No. Browsers and Zora both wait for a tap — nothing plays until you ask."}]},{"type":"cta","title":"Quiet sounds, when you want them.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Ambient weather sounds in Zora | Zora$c$, $c$Turn on Zora's ambient weather sounds — soft rain, thunder, breeze, still air, quiet night — set the volume, and mute them any time.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$settings$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$going-ad-free$c$, $c$Going ad-free: plans and promo codes$c$, $c$Zora is free with one small, still ad. Going ad-free removes it — every other feature is the same on every plan.$c$, $c$[{"type":"callout","title":"The short version","text":"Every plan has every feature. Paying only removes the ad — on up to five screens with one free account. Choose **Monthly** (cancel any time) or **Lifetime** (pay once)."},{"type":"heading","text":"What free looks like"},{"type":"paragraph","text":"One small image ad along the bottom, labelled “Ad”, with no animation, video or sound. It's dimmed at night. If there's no ad to show, the space stays empty."},{"type":"heading","text":"The plans"},{"type":"table","caption":"Current prices are shown on the plan screen and Zora's website.","header":["Plan","How it works"],"rows":[["Free","Every feature, with one small, still ad"],["Monthly","Ad-free, billed monthly. Cancel any time"],["Lifetime","Ad-free, pay once. Yours for good"]]},{"type":"heading","text":"Going ad-free"},{"type":"list","ordered":true,"items":["On the car screen, open **Settings** and tap **Sign in for ad-free** (or **See plans**).","Sign in with your phone or an email code — see [Signing in a car screen with your phone](/guides/zora/signing-in-a-car-screen).","Choose a plan and tap **Continue with Monthly** or **Continue with Lifetime**. Payment is handled by Stripe; Zora never sees or stores your card.","You'll see “Ads are gone. Thank you.”"]},{"type":"heading","text":"Promo codes"},{"type":"paragraph","text":"Enter a code in **Promo code** and tap **Apply** before checkout. A discount code shows the saving, applied at checkout; a free-trial code starts straight away. Codes need you to be signed in, and each can be used once per account."},{"type":"faq","items":[{"q":"How do I cancel a monthly plan?","a":"On your phone, open the account page and tap **Manage subscription and receipts**."},{"q":"What if new plans are paused?","a":"You'll see “New ad-free plans are paused right now.” Plans people already have keep working."}]},{"type":"cta","title":"Clear skies, no ads.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, true, $c$Go ad-free in Zora: plans and promo codes | Zora$c$, $c$What the free plan includes, the monthly and lifetime ad-free plans, using a promo code, and how payment works.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$ad-free-and-account$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$signing-in-a-car-screen$c$, $c$Signing in a car screen with your phone$c$, $c$Typing an email on a car screen is a pain. Scan a code with your phone instead, approve it, and the car screen signs itself in.$c$, $c$[{"type":"callout","title":"The short version","text":"On the car: **Settings › Sign in for ad-free**. Scan the QR code with your phone, sign in, and tap **Approve** — only if the code on your phone matches the one on the car."},{"type":"heading","text":"With the QR code"},{"type":"list","ordered":true,"items":["On the car screen, open **Settings** and tap **Sign in for ad-free**.","Scan the QR code with your phone's camera.","Sign in with the 6-digit code Zora emails you. New here? This creates your free account.","Check your car is showing the same code, then tap **Approve**.","The car says “Approved. Signing in this screen…” — you can put your phone away."]},{"type":"heading","text":"Without scanning"},{"type":"paragraph","text":"Open **zoraapp.midnightpoetry.studio/account** on your phone and type the eight-character code from the car screen (like ABCD-2345). Codes last 10 minutes; if it expires, tap **Show a new code**. Prefer typing on the car? Choose **Type an email on this screen instead**."},{"type":"heading","text":"Up to five screens"},{"type":"paragraph","text":"One account covers five screens — your phone's account page doesn't count. Signing in a sixth screen signs out the one used longest ago. To free a screen yourself, go to **Settings › Ad-free › Manage › Sign out of this screen** on that screen; it brings the ad back there without cancelling your plan."},{"type":"faq","items":[{"q":"Someone else's code appeared on my phone.","a":"Tap **Not me**. Only approve a code your own car screen is showing right now."},{"q":"Do I need a password?","a":"No. Zora signs you in with a 6-digit code sent by email, valid for 10 minutes."}]},{"type":"cta","title":"One account, up to five screens.","text":"","label":"Open your account","url":"https://zoraapp.midnightpoetry.studio/account"}]$c$::jsonb, false, $c$Sign in a car screen with your phone | Zora$c$, $c$Sign a car screen into your Zora account by scanning a QR code or entering a short code on your phone, and manage up to five screens.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$ad-free-and-account$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;

insert into public.guides (product_id, category_id, slug, title, standfirst, blocks, start_here, meta_title, meta_description, author_name, status)
select p.id, c.id, $c$your-location-and-privacy$c$, $c$Your location and privacy$c$, $c$Zora needs a rough idea of where you are to show the weather — and nothing more. Here is exactly what happens to your location and what an account keeps.$c$, $c$[{"type":"callout","title":"The short version","text":"Your location is rounded to about 1 km on your device and never stored on our servers. Settings never leave the screen. You don't need an account at all unless you go ad-free."},{"type":"heading","text":"Your location"},{"type":"list","ordered":false,"items":["Rounded to about 1 km on your device, then again on the way out.","Passed through Zora's own server to the weather service, so the weather provider never sees your IP address.","Never stored on our servers. Only the last report's rounded position is kept on your device.","Don't want to share it? Choose **A city** instead."]},{"type":"heading","text":"What stays on the device"},{"type":"paragraph","text":"Every setting — clock, world clocks, colours, sounds — is saved on that screen only. Clearing the browser's data resets them."},{"type":"heading","text":"What an account keeps"},{"type":"paragraph","text":"Only if you go ad-free: your email, your plan and payment history, and up to five screens (stored as scrambled identifiers with when each was last used). Card details stay with Stripe."},{"type":"heading","text":"Ads on the free plan"},{"type":"paragraph","text":"Zora counts how often an ad is shown and tapped each day, without identifying you. Where an ad network is used, visitors who must be asked for consent are asked first."},{"type":"heading","text":"Deleting your account"},{"type":"paragraph","text":"On your phone's account page, tap **Delete account**, type DELETE and confirm. Every screen is signed out and a monthly plan is cancelled straight away. A lifetime plan can't be restored afterwards. Payment records are kept for accounting, without your personal details."},{"type":"faq","items":[{"q":"Does Zora track where I drive?","a":"No. It only asks for an approximate position to fetch the weather, and doesn't keep a history."}]},{"type":"cta","title":"Weather, without the tracking.","text":"","label":"Open Zora","url":"https://zoraapp.midnightpoetry.studio/"}]$c$::jsonb, false, $c$Zora, your location and your privacy | Zora$c$, $c$How Zora rounds and protects your location, what stays on your device, what an account stores, and how to delete your account.$c$, 'Midnight Poetry Studio', 'published'
from public.products p join public.categories c on c.product_id = p.id and c.slug = $c$privacy$c$
where p.slug = $c$zora$c$
on conflict (product_id, slug) do nothing;
